import type { ReactNode } from 'react'
import { useRouter } from 'next/navigation'

type RouterButtonProps = {
  children: ReactNode
  href?: string
  back?: boolean
}

export function RouterButton({
  children,
  href,
  back = false,
}: RouterButtonProps) {
  const router = useRouter()

  return (
    <button
      type="button"
      onClick={() => {
        if (back) {
          router.back()
          return
        }

        if (href) {
          router.push(href)
        }
      }}
    >
      {children}
    </button>
  )
}

