import { cache } from 'react'
import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { RouterButton } from '@/components/RouterButton'
import type { BlogComment, BlogPost } from '@/lib/types'

export const revalidate = 300
export const dynamicParams = true

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

const getBlogPost = cache(async (id: string) => {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }).then((res) => res.json() as Promise<BlogPost>),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }).then((res) => res.json() as Promise<BlogComment[]>),
    ])

    return { post, comments }
  } catch {
    notFound()
  }
})

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = (await fetch('https://jsonplaceholder.typicode.com/posts').then(
    (res) => res.json()
  )) as BlogPost[]

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const { post } = await getBlogPost(id)
  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const { post, comments } = await getBlogPost(id)

  return (
    <article>
      <RouterButton back>← Back</RouterButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

